const root=document.querySelector('#app'), modal=document.querySelector('#modal');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let session={}, data={garments:[],outfits:[],wears:[],revision:0}, page='today', selectedDay='', calendarMonth='', clothingFilter={q:'',category:'',archived:'active'}, statsFilter={from:'',to:'',category:''};
let spendingPeriod='6';
const titles={today:'Tu armario, en perspectiva',garments:'Mi ropa',outfits:'Mis outfits',calendar:'Calendario',stats:'Compras y estadísticas',settings:'Ajustes y respaldos'};
const glyphs={today:'◷',garments:'▦',outfits:'◈',calendar:'▤',stats:'▥',settings:'⚙'};
const navNames={today:'Inicio',garments:'Mi ropa',outfits:'Outfits',calendar:'Historial',stats:'Estadísticas',settings:'Ajustes'};
const photo=id=>`api.php?action=photo&id=${encodeURIComponent(id)}`;
const dateLabel=d=>d?new Intl.DateTimeFormat('es',{day:'numeric',month:'long',year:'numeric'}).format(new Date(`${d}T12:00:00`)):'Sin fecha';
const dateShort=d=>new Intl.DateTimeFormat('es',{day:'numeric',month:'short'}).format(new Date(`${d}T12:00:00`));
const money=(n,c)=>`${new Intl.NumberFormat('es',{minimumFractionDigits:session.currencies[c]??2,maximumFractionDigits:session.currencies[c]??2}).format(n/(10**(session.currencies[c]??2)))} ${c}`;
function notify(msg){const t=document.querySelector('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(notify.timer);notify.timer=setTimeout(()=>t.classList.remove('show'),5000);}
async function api(action,body){
  const init={credentials:'same-origin',cache:'no-store'};
  if(body!==undefined){init.method='POST';init.headers={'X-CSRF-Token':session.csrf};if(body instanceof FormData)init.body=body;else {init.headers['Content-Type']='application/json';init.body=JSON.stringify(body);}}
  let r;try{r=await fetch(`api.php?action=${action}`,init);}catch{throw Error('No hay conexión con la aplicación. Tus cambios siguen en el formulario; vuelve a intentar cuando recuperes la conexión.');}
  let json;try{json=await r.json();}catch{throw Error('El servidor no pudo procesar el archivo o la petición. Consulta el límite de subida del alojamiento.');}
  if(!r.ok){if(r.status===401&&action!=='login'){modal.close();data={garments:[],outfits:[],wears:[],revision:0};session=await api('session');renderLogin();}throw Error(json.error||'No se pudo completar la operación.');}return json;
}
async function refresh(){data=await api('state');render();}
function options(values,selected='',blank='Todas las categorías'){return `<option value="">${esc(blank)}</option>`+values.map(v=>`<option ${v===selected?'selected':''} value="${esc(v)}">${esc(v)}</option>`).join('');}
function empty(title,text,action,label){return `<div class="empty"><span class="empty-mark" aria-hidden="true">＋</span><h2>${title}</h2><p>${text}</p>${action?`<button class="primary" data-action="${action}">${label}</button>`:''}</div>`;}
function headerAction(){return page==='garments'?'<button class="primary" data-action="new-garment">＋ Añadir prenda</button>':page==='outfits'?'<button class="primary" data-action="new-outfit">＋ Crear outfit</button>':['today','calendar'].includes(page)?'<button class="primary" data-action="new-wear">＋ Registrar uso</button>':'';}
function render(){
 root.classList.add('wardrobe');
 root.innerHTML=`<aside class="sidebar"><a class="brand" href="#today"><span class="monogram">M</span><span>mi armario<small>Un espacio para tu ropa</small></span></a><nav aria-label="Principal">${Object.keys(titles).map(k=>`<button data-page="${k}" ${page===k?'aria-current="page"':''}><span aria-hidden="true">${glyphs[k]}</span><span>${navNames[k]}</span></button>`).join('')}</nav><div class="sidebar-foot"><span class="privacy">Solo para ti</span><button class="text-button" data-action="logout">Cerrar sesión ↗</button></div></aside><main><div class="topline"><span>${session.local?'PRUEBA LOCAL · MAC':'MI ESPACIO PERSONAL'}</span><button class="text-button" data-action="refresh">↻ Actualizar</button></div><header class="page-heading"><div><p class="eyebrow">${page==='today'?esc(dateLabel(session.today)):'MI ARMARIO'}</p><h1>${titles[page]}</h1></div>${headerAction()}</header><div id="content">${({today:todayView,garments:garmentsView,outfits:outfitsView,calendar:calendarView,stats:statsView,settings:settingsView})[page]()}</div></main>`;
}
function outfitImages(o){if(o.photo)return `<img src="${photo(o.photo)}" alt="${esc(o.name)}" loading="lazy">`;return `<div class="collage">${o.garment_ids.slice(0,4).map(id=>{const g=data.garments.find(g=>g.id===id);return g?garmentImage(g):placeholder();}).join('')}</div>`;}
function garmentCard(g){const uses=data.wears.filter(w=>w.items.some(i=>i.id===g.id));const last=uses.map(w=>w.date).sort().at(-1);return `<article class="card"><button class="picture" data-action="edit-garment" data-id="${g.id}" aria-label="Editar ${esc(g.name)}">${garmentImage(g)}${g.archived?'<span class="badge">Archivada</span>':''}</button><div class="card-body"><p class="eyebrow">${esc(g.category)} · ${esc(g.color)}</p><h3>${esc(g.name)}</h3>${garmentSize(g)?`<p class="muted">Talla ${esc(garmentSize(g))}</p>`:''}${isPants(g)?`<p class="muted">${esc(g.pants_type||'Tipo sin especificar')}${g.pants_model?' · Modelo '+esc(g.pants_model):''}</p>`:''}${tagPills(g.tags)}<p class="muted">${uses.length} ${uses.length===1?'uso':'usos'}${last?' · '+dateShort(last):' · Aún por estrenar'}</p><button class="text-button" data-action="edit-garment" data-id="${g.id}">Ver y editar →</button></div></article>`;}
function outfitCard(o){return `<article class="card"><button class="picture" data-action="edit-outfit" data-id="${o.id}" aria-label="Editar ${esc(o.name)}">${outfitImages(o)}</button><div class="card-body"><p class="eyebrow">${o.garment_ids.length} ${o.garment_ids.length===1?'prenda':'prendas'}</p><h3>${esc(o.name)}</h3>${tagPills(o.tags)}<div class="card-bottom"><span class="muted">${data.wears.filter(w=>w.outfit_id===o.id).length} usos</span><button class="small-button" data-action="wear-outfit" data-id="${o.id}">Lo llevo hoy</button></div></div></article>`;}
function wearRow(w){return `<article class="wear-row"><div class="wear-thumbs">${w.items.slice(0,3).map(i=>{const g=data.garments.find(g=>g.id===i.id);return g?garmentImage(g):placeholder();}).join('')}</div><div class="wear-copy"><h3>${esc(w.outfit_name||'Combinación del día')}</h3><p>${esc(dateLabel(w.date))} · ${w.items.length} ${w.items.length===1?'prenda':'prendas'}</p><p class="muted">${w.items.map(i=>esc(i.name)).join(' · ')}</p>${w.notes?`<p>${esc(w.notes)}</p>`:''}</div><button class="small-button" data-action="edit-wear" data-id="${w.id}">Corregir</button></article>`;}
function isPants(g){return ['Pantalones','Jeans'].includes(g.category);}
function garmentSize(g){
 if(isPants(g)&&(g.waist||g.length))return g.waist&&g.length?`${g.waist}x${g.length}`:g.waist?`Cintura ${g.waist} · largo sin especificar`:`Largo ${g.length} · cintura sin especificar`;
 return g.size||'';
}
// Only recorded purchase dates become points. Gaps are not imputed as purchases.
function spendingData(garments,today,period){
 let from='';
 if(period==='30'){const d=new Date(today+'T12:00:00Z');d.setUTCDate(d.getUTCDate()-29);from=d.toISOString().slice(0,10);}
 else if(['3','6','12'].includes(period)){const d=new Date(today.slice(0,7)+'-01T12:00:00Z');d.setUTCMonth(d.getUTCMonth()-Number(period)+1);from=d.toISOString().slice(0,10);}
 const groups=new Map();
 for(const g of garments){
  if(!g.purchase_date||g.purchase_date>today||(from&&g.purchase_date<from)||!Number.isSafeInteger(g.price_minor)||!g.currency)continue;
  const key=period==='30'?g.purchase_date:g.purchase_date.slice(0,7);
  if(!groups.has(g.currency))groups.set(g.currency,new Map());
  const points=groups.get(g.currency);points.set(key,(points.get(key)||0)+g.price_minor);
 }
 return [...groups].sort(([a],[b])=>a.localeCompare(b)).map(([currency,points])=>({currency,points:[...points].sort(([a],[b])=>a.localeCompare(b)).map(([date,value])=>({date,value}))}));
}
function spendingChart(series){
 const {currency,points}=series,max=Math.max(1,...points.map(p=>p.value)),left=76,right=528,top=22,bottom=194;
 const stamp=d=>Date.parse((d.length===7?d+'-01':d)+'T12:00:00Z');
 const first=stamp(points[0].date),span=stamp(points.at(-1).date)-first;
 const dots=points.map(p=>({...p,x:span?left+(stamp(p.date)-first)/span*(right-left):(left+right)/2,y:bottom-p.value/max*(bottom-top)}));
 // Horizontal tangents keep the curve between adjacent observed values, with no overshoot.
 const line=dots.map((p,i)=>i?`C ${(dots[i-1].x+p.x)/2} ${dots[i-1].y}, ${(dots[i-1].x+p.x)/2} ${p.y}, ${p.x} ${p.y}`:`M ${p.x} ${p.y}`).join(' ');
 const label=d=>new Intl.DateTimeFormat('es',d.length===7?{month:'short',year:'2-digit',timeZone:'UTC'}:{day:'numeric',month:'short',timeZone:'UTC'}).format(new Date(stamp(d)));
 const labels=new Set([0,Math.round((dots.length-1)/3),Math.round(2*(dots.length-1)/3),dots.length-1]);
 return `<div class="spending-series"><h3>${esc(currency)} <span class="muted">· ${esc(money(points.reduce((n,p)=>n+p.value,0),currency))} en el periodo</span></h3><svg class="spending-chart" viewBox="0 0 560 242" role="img" aria-label="Gasto registrado en ${esc(currency)}. ${points.length} periodos con compras; datos detallados debajo.">${[0,.5,1].map(f=>`<line class="chart-gridline" x1="${left}" x2="${right}" y1="${bottom-f*(bottom-top)}" y2="${bottom-f*(bottom-top)}"/><text class="chart-axis" x="68" y="${bottom-f*(bottom-top)+4}" text-anchor="end">${esc(new Intl.NumberFormat('es',{notation:'compact',maximumFractionDigits:1}).format(f*max/10**(session.currencies[currency]??2)))}</text>`).join('')}${dots.length>1?`<path class="spending-line" d="${line}"/>`:''}${dots.map((p,i)=>`<circle class="spending-point" cx="${p.x}" cy="${p.y}" r="4.5"><title>${esc(p.date)}: ${esc(money(p.value,currency))}</title></circle>${labels.has(i)?`<text class="chart-axis" x="${p.x}" y="220" text-anchor="${i===0&&dots.length>1?'start':i===dots.length-1&&dots.length>1?'end':'middle'}">${esc(label(p.date))}</text>`:''}`).join('')}</svg><details><summary>Ver importes exactos · ${points.length} ${spendingPeriod==='30'?(points.length===1?'día':'días'):(points.length===1?'mes':'meses')} con compras</summary><div class="table-wrap"><table><thead><tr><th>Fecha</th><th>Gasto (${esc(currency)})</th></tr></thead><tbody>${points.map(p=>`<tr><td>${esc(p.date)}</td><td>${esc(money(p.value,currency))}</td></tr>`).join('')}</tbody></table></div></details></div>`;
}
function spendingView(){
 const series=spendingData(data.garments,session.today,spendingPeriod);
 return `<section class="panel spending-panel"><div class="section-heading"><div><p class="eyebrow">COMPRAS CON PRECIO Y FECHA</p><h2>Evolución del gasto</h2></div><label>Periodo<select id="spending-period">${[['30','Últimos 30 días'],['3','Últimos 3 meses'],['6','Últimos 6 meses'],['12','Últimos 12 meses'],['all','Todo el historial']].map(([v,l])=>`<option value="${v}" ${v===spendingPeriod?'selected':''}>${l}</option>`).join('')}</select></label></div>${series.length?series.map(spendingChart).join(''):'<p class="chart-empty">No hay compras con precio y fecha en este periodo.</p>'}<p class="chart-note">${spendingPeriod==='30'?'Gasto diario: hoy y los 29 días anteriores.':'Gasto mensual: incluye el mes actual hasta hoy.'} Cada moneda se muestra por separado. Solo aparecen puntos con compras registradas; la línea es una guía visual, no una estimación de los intervalos sin registros. Las compras sin fecha o precio no se incluyen.</p></section>`;
}
// Pure aggregation: only persisted records are inputs. Missing fields stay unspecified.
function dashboardData(state,today){
 const active=state.garments.filter(g=>!g.archived), counts=new Map(), last=new Map(), categories=new Map();
 const monthIds=new Set(), outfitUses=new Map();
 for(const w of state.wears){
  if(w.date>today)continue;
  const seen=new Set();
  for(const i of w.items){if(seen.has(i.id))continue;seen.add(i.id);counts.set(i.id,(counts.get(i.id)||0)+1);if(w.date>(last.get(i.id)||''))last.set(i.id,w.date);categories.set(i.category,(categories.get(i.category)||0)+1);if(w.date.slice(0,7)===today.slice(0,7))monthIds.add(i.id);}
  if(w.outfit_id)outfitUses.set(w.outfit_id,(outfitUses.get(w.outfit_id)||0)+1);
 }
 const distribution=(items,key)=>{const map=new Map();for(const item of items){const label=item[key]||'Sin especificar';map.set(label,(map.get(label)||0)+1);}return [...map].map(([name,n])=>({name,n})).sort((a,b)=>b.n-a.n||a.name.localeCompare(b.name,'es'));};
 const spend=new Map(), pricedUsage=new Map(), monthly=new Map(), best=new Map();
 const ranked=state.garments.map(g=>({g,n:counts.get(g.id)||0,last:last.get(g.id)||null}));
 for(const {g,n} of ranked){
  if(!Number.isSafeInteger(g.price_minor)||!g.currency)continue;
  spend.set(g.currency,(spend.get(g.currency)||0)+g.price_minor);
  if(n){const value=pricedUsage.get(g.currency)||{price:0,uses:0};value.price+=g.price_minor;value.uses+=n;pricedUsage.set(g.currency,value);const cpu=g.price_minor/n;if(!best.has(g.currency)||cpu<best.get(g.currency).cpu)best.set(g.currency,{g,cpu});}
  if(g.purchase_date&&g.purchase_date<=today){const key=g.purchase_date.slice(0,7)+'|'+g.currency;monthly.set(key,(monthly.get(key)||0)+g.price_minor);}
 }
 const tags=new Map(), tagUses=new Map();
 for(const o of state.outfits){const seen=new Set();for(const label of o.tags||[]){const key=label.toLocaleLowerCase('es');if(seen.has(key))continue;seen.add(key);const row=tags.get(key)||{name:label,n:0};row.n++;tags.set(key,row);const n=outfitUses.get(o.id)||0;if(n){const used=tagUses.get(key)||{name:label,n:0};used.n+=n;tagUses.set(key,used);}}}
 const since=date=>Math.floor((Date.parse(today+'T12:00:00Z')-Date.parse(date+'T12:00:00Z'))/86400000);
 return {active:active.length,total:state.garments.length,usedMonth:monthIds.size,outfits:state.outfits.length,tagCount:tags.size,
  spend:[...spend],cost:[...pricedUsage].map(([c,v])=>[c,v.price/v.uses]),monthly:[...monthly].sort(([a],[b])=>a.localeCompare(b)),
  sizes:distribution(active.map(g=>({...g,size:garmentSize(g)})),'size'),pants:distribution(active.filter(g=>['Pantalones','Jeans'].includes(g.category)),'pants_type'),
  categories:[...categories].map(([name,n])=>({name,n})).sort((a,b)=>b.n-a.n),tags:[...tags.values()].sort((a,b)=>b.n-a.n),tagUses:[...tagUses.values()].sort((a,b)=>b.n-a.n),best:[...best],
  most:ranked.filter(x=>x.n>0).sort((a,b)=>b.n-a.n||a.g.name.localeCompare(b.g.name,'es')).slice(0,4),
  least:ranked.filter(x=>!x.g.archived).sort((a,b)=>a.n-b.n||a.g.name.localeCompare(b.g.name,'es')).slice(0,4),
  neglected:ranked.filter(x=>!x.g.archived&&x.last&&since(x.last)>=90).map(x=>({...x,days:since(x.last)})).sort((a,b)=>b.days-a.days),
  never:ranked.filter(x=>!x.g.archived&&!x.n).length,
  recent:[...state.wears].filter(w=>w.date<=today&&w.outfit_id).sort((a,b)=>b.date.localeCompare(a.date)).slice(0,3)
 };
}
const placeholder=()=>'<span class="neutral-photo" role="img" aria-label="Sin foto">◇<small>Sin foto</small></span>';
function garmentImage(g){return g?.photo?`<img src="${photo(g.photo)}" alt="${esc(g.name)}" loading="lazy">`:placeholder();}
function tagPills(tags=[]){return tags.length?`<div class="tag-pills">${tags.map(t=>`<span>${esc(t)}</span>`).join('')}</div>`:'';}
function chartBars(rows,unit='prendas',blank='Todavía no hay datos para esta gráfica.'){
 if(!rows.length)return `<p class="chart-empty">${esc(blank)}</p>`;
 const max=Math.max(1,...rows.map(r=>r.n));
 return `<div class="chart-bars">${rows.map(r=>`<div class="chart-row"><div><span>${esc(r.name)}</span><strong>${esc(r.label??r.n)}</strong></div><meter min="0" max="${max}" value="${r.n}" aria-label="${esc(r.name)}: ${esc(r.label??r.n)} ${esc(unit)}">${r.n}</meter></div>`).join('')}</div>`;
}
function dashboardRows(rows){return rows.length?`<div class="dashboard-list">${rows.map(({g,n,last})=>`<button class="dashboard-item" data-action="edit-garment" data-id="${g.id}">${garmentImage(g)}<span><strong>${esc(g.name)}</strong><small>${esc(g.category)}${g.archived?' · Archivada':''}</small><small>${n} ${n===1?'uso':'usos'}${g.price_minor!==null&&g.price_minor!==undefined&&n?' · '+esc(money(g.price_minor/n,g.currency))+'/uso':''}</small>${last?`<small>Último: ${esc(dateShort(last))}</small>`:''}</span><span aria-hidden="true">↗</span></button>`).join('')}</div>`:'<p class="chart-empty">Tus prendas aparecerán aquí cuando haya datos.</p>';}
function todayView(){
 const s=dashboardData(data,session.today),today=data.wears.filter(w=>w.date===session.today);
 const amounts=rows=>rows.length?rows.map(([c,n])=>`<span>${esc(money(n,c))}</span>`).join(''):'<span>Sin datos</span>';
 const metric=(label,value,note)=>`<article class="metric"><p>${label}</p><div class="metric-value">${value}</div><small>${note}</small></article>`;
 const insights=[];
 if(s.categories.length)insights.push(`Categoría con más usos: <strong>${esc(s.categories[0].name)}</strong> · ${s.categories[0].n} usos de prendas${s.categories.filter(x=>x.n===s.categories[0].n).length>1?' (empatada)':''}.`);
 for(const [c,{g,cpu}] of s.best)insights.push(`Menor costo por uso en ${esc(c)}: <strong>${esc(g.name)}</strong> · ${esc(money(cpu,c))}/uso (puede haber empates).`);
 if(s.tagUses.length)insights.push(`Etiqueta de outfit con más usos: <strong>${esc(s.tagUses[0].name)}</strong> · ${s.tagUses[0].n} registros${s.tagUses.filter(x=>x.n===s.tagUses[0].n).length>1?' (empatada)':''}.`);
 if(s.neglected.length)insights.push(`<strong>${s.neglected.length} prendas activas</strong> llevan al menos 90 días sin uso registrado. ${esc(s.neglected[0].g.name)}: ${s.neglected[0].days} días.`);
 if(s.never)insights.push(`<strong>${s.never} prendas activas</strong> aún no tienen ningún uso registrado.`);
 return `<p class="dashboard-intro">Una mirada a lo que tienes, lo que llevas y lo que aprovechas.</p><section class="quick-wear"><div><p class="eyebrow">TU REGISTRO DEL DÍA</p><h2>${today.length?'Lo de hoy ya tiene su lugar.':'¿Qué llevas hoy?'}</h2><p>${today.length?`${today.length} ${today.length===1?'uso registrado':'usos registrados'} hoy.`:'Guarda tu combinación en unos toques.'}</p></div><div class="quick-actions"><button class="primary" data-action="new-wear">＋ Registrar uso</button><button class="small-button" data-action="new-garment">Añadir prenda</button></div></section>${today.map(wearRow).join('')}
 <div class="metrics-grid">${metric('Total de prendas',s.total,`${s.active} activas · ${s.total-s.active} archivadas`)}${metric('Prendas usadas este mes',s.usedMonth,'Prendas distintas · incluye archivadas')}${metric('Gasto registrado',amounts(s.spend),'Precios guardados · monedas separadas')}${metric('Costo por uso',amounts(s.cost),'Precio total ÷ usos de prendas con precio y uso')}${metric('Outfits guardados',s.outfits,'Guardar no cuenta como uso')}${metric('Etiquetas de outfits',s.tagCount,'Etiquetas distintas asignadas')}</div>
 ${spendingView()}<div class="dashboard-grid"><section class="panel"><p class="eyebrow">TODO EL HISTORIAL</p><h2>Uso por categoría</h2>${chartBars(s.categories,'usos','Registra un uso para ver tus categorías.') }<p class="chart-note">Cada prenda del registro cuenta una vez; se conserva su categoría histórica.</p></section>
 <section class="panel"><p class="eyebrow">PRENDAS ACTIVAS</p><h2>Distribución por talla</h2>${chartBars(s.sizes)}<p class="chart-note">Las tallas sin completar se muestran por separado.</p></section>
 <section class="panel"><div class="section-heading"><h2>Más usadas</h2><button class="text-button" data-page="stats">Ver más →</button></div>${dashboardRows(s.most)}</section>
 <section class="panel"><h2>Menos usadas</h2><p class="chart-note">Prendas activas · incluye las nunca usadas.</p>${dashboardRows(s.least)}</section>
 <section class="panel"><h2>Últimos outfits llevados</h2>${s.recent.length?s.recent.map(wearRow).join(''):'<p class="chart-empty">Aquí verás los outfits que registres como usados, con su fecha real.</p>'}</section>
 <section class="panel"><p class="eyebrow">PANTALONES Y JEANS ACTIVOS</p><h2>Tipos de pantalón</h2>${chartBars(s.pants)}<p class="chart-note">Solo tipos seleccionados por ti; no se deducen de las fotos.</p></section>
 <section class="panel"><p class="eyebrow">OUTFITS GUARDADOS</p><h2>Tus etiquetas</h2>${chartBars(s.tags,'outfits','Selecciona etiquetas en tus outfits para ver su distribución.')}<p class="chart-note">Un outfit puede pertenecer a varias etiquetas. Los usos por etiqueta utilizan las etiquetas actuales.</p></section>
 <section class="panel insights"><p class="eyebrow">TU ARMARIO, CON PERSPECTIVA</p><h2>Lo que cuentan tus registros</h2>${insights.length?`<ul>${insights.map(i=>`<li>${i}</li>`).join('')}</ul>`:'<p class="chart-empty">A medida que guardes prendas y usos, aquí aparecerán observaciones basadas en ellos.</p>'}</section></div>
 <div class="section-heading"><h2>Listos para volver a salir</h2><button class="text-button" data-page="outfits">Ver outfits →</button></div>${data.outfits.length?`<div class="grid">${data.outfits.slice(-4).reverse().map(outfitCard).join('')}</div>`:empty('Tu próxima combinación empieza aquí','Selecciona prendas reales de tu armario para crear un outfit.','new-outfit','Crear outfit')}`;
}

function clothingResults(){const f=clothingFilter;return data.garments.filter(g=>(!f.q||`${g.name} ${g.color} ${g.notes} ${garmentSize(g)} ${g.pants_model||''} ${g.pants_type||''} ${(g.tags||[]).join(' ')}`.toLocaleLowerCase('es').includes(f.q.toLocaleLowerCase('es')))&&(!f.category||g.category===f.category)&&(f.archived==='all'||g.archived===(f.archived==='archived')));}
function garmentsView(){return `<div class="filters"><label class="search">Buscar prendas<input id="clothing-q" type="search" placeholder="Nombre, color o notas…" value="${esc(clothingFilter.q)}"></label><label>Categoría<select id="clothing-category">${options(session.categories,clothingFilter.category)}</select></label><label>Mostrar<select id="clothing-archived"><option value="active" ${clothingFilter.archived==='active'?'selected':''}>Activas</option><option value="archived" ${clothingFilter.archived==='archived'?'selected':''}>Archivadas</option><option value="all" ${clothingFilter.archived==='all'?'selected':''}>Todas</option></select></label></div><div id="clothing-results">${garmentResults()}</div>`;}
function garmentResults(){const gs=clothingResults();return gs.length?`<p class="result-count">${gs.length} prendas</p><div class="grid">${gs.map(garmentCard).join('')}</div>`:empty('Aquí hay espacio para tu ropa',data.garments.length?'No hay prendas con estos filtros.':'Añade una foto y los detalles de tu primera prenda.','new-garment','Añadir prenda');}
function outfitsView(){return data.outfits.length?`<p class="intro">Guarda una combinación una vez. Llévala todos los días que quieras.</p><div class="grid">${data.outfits.map(outfitCard).join('')}</div>`:empty('Combinaciones que funcionan','Elige prendas de tu armario. Guardar un outfit no cuenta como uso.','new-outfit','Crear outfit');}
function calendarView(){calendarMonth ||=session.today.slice(0,7);selectedDay ||=session.today;const [year,month]=calendarMonth.split('-').map(Number);const first=(new Date(year,month-1,1).getDay()+6)%7;const days=new Date(year,month,0).getDate();const ws=data.wears.filter(w=>w.date===selectedDay);return `<div class="calendar-layout"><section class="panel"><div class="calendar-controls"><button class="small-button" data-action="prev-month" aria-label="Mes anterior">←</button><label>Mes<input type="month" id="calendar-month" value="${calendarMonth}"></label><button class="small-button" data-action="next-month" aria-label="Mes siguiente">→</button></div><div class="calendar-grid">${['L','M','X','J','V','S','D'].map(d=>`<span class="weekday">${d}</span>`).join('')}${Array.from({length:first},()=>'<span></span>').join('')}${Array.from({length:days},(_,i)=>{const d=`${calendarMonth}-${String(i+1).padStart(2,'0')}`,n=data.wears.filter(w=>w.date===d).length;return `<button ${d>session.today?'disabled':''} data-action="select-day" data-date="${d}" ${d===selectedDay?'aria-pressed="true"':'aria-pressed="false"'} aria-label="${esc(dateLabel(d))}, ${n} usos"><span>${i+1}</span>${n?`<small>${n} ${n===1?'uso':'usos'}</small>`:''}</button>`;}).join('')}</div></section><section><div class="section-heading"><h2>${esc(dateLabel(selectedDay))}</h2></div>${ws.length?ws.map(wearRow).join(''):empty('Un día por registrar','Puedes añadir un uso de hoy o de una fecha anterior.','new-wear','Registrar este día')}</section></div>`;}
function statsData(){const f=statsFilter;const inRange=d=>!!d&&(!f.from||d>=f.from)&&(!f.to||d<=f.to);const ws=data.wears.filter(w=>inRange(w.date)&&(!f.category||w.items.some(i=>i.category===f.category)));const gs=data.garments.filter(g=>!f.category||g.category===f.category||ws.some(w=>w.items.some(i=>i.id===g.id&&i.category===f.category)));const counts=gs.map(g=>({g,n:ws.filter(w=>w.items.some(i=>i.id===g.id&&(!f.category||i.category===f.category))).length}));const months={};if(ws.length){const start=(f.from||ws.map(w=>w.date).sort()[0]).slice(0,7);const end=(f.to||session.today).slice(0,7);let [y,m]=start.split('-').map(Number);while(`${y}-${String(m).padStart(2,'0')}`<=end){months[`${y}-${String(m).padStart(2,'0')}`]=0;if(++m===13){m=1;y++;}}}ws.forEach(w=>months[w.date.slice(0,7)]=(months[w.date.slice(0,7)]||0)+1);const repeats=data.outfits.map(o=>({name:o.name,n:ws.filter(w=>w.outfit_id===o.id).length})).filter(o=>o.n>0).sort((a,b)=>b.n-a.n);const purchases=gs.filter(g=>(!f.category||g.category===f.category)&&g.purchase_date&&inRange(g.purchase_date));const expenses={};purchases.forEach(g=>{if(g.price_minor!==null){const key=g.purchase_date.slice(0,7)+'|'+g.currency;expenses[key]=(expenses[key]||0)+g.price_minor;}});return{ws,gs,counts,months,repeats,purchases,expenses};}
function bars(rows,emptyText='No hay usos en este periodo.'){if(!rows.length)return `<p class="muted">${emptyText}</p>`;const max=Math.max(1,...rows.map(x=>x.n));return `<div class="bars">${rows.map(x=>`<div class="bar"><div><span>${esc(x.name)}</span><strong>${x.n}</strong></div><meter min="0" max="${max}" value="${x.n}" aria-label="${esc(x.name)}: ${x.n} usos">${x.n}</meter></div>`).join('')}</div>`;}
function statsView(){const s=statsData();const never=s.gs.filter(g=>!data.wears.some(w=>w.items.some(i=>i.id===g.id)));return `<div class="filters"><label>Desde<input type="date" id="stats-from" value="${statsFilter.from}" max="${session.today}"></label><label>Hasta<input type="date" id="stats-to" value="${statsFilter.to}" max="${session.today}"></label><label>Categoría<select id="stats-category">${options(session.categories,statsFilter.category)}</select></label><button class="text-button" data-action="clear-stats">Limpiar filtros</button></div>${statsFilter.from&&statsFilter.to&&statsFilter.from>statsFilter.to?'<p class="error">La fecha inicial debe ser anterior a la final.</p>':''}<div class="summary-strip"><div><strong>${s.ws.length}</strong><span>usos en el periodo</span></div><div><strong>${s.gs.length}</strong><span>prendas · incluye archivadas</span></div><div><strong>${never.length}</strong><span>nunca usadas · todo el historial</span></div></div><div class="stats-grid"><section class="panel"><h2>Más usadas</h2>${bars([...s.counts].filter(x=>x.n>0).sort((a,b)=>b.n-a.n).slice(0,8).map(x=>({name:x.g.name,n:x.n})))}</section><section class="panel"><h2>Menos usadas</h2>${bars([...s.counts].sort((a,b)=>a.n-b.n).slice(0,8).map(x=>({name:x.g.name,n:x.n})),'Añade prendas para comenzar.')}</section><section class="panel"><h2>Outfits más repetidos</h2>${bars(s.repeats.slice(0,8))}</section><section class="panel"><h2>Uso por mes</h2>${bars(Object.entries(s.months).sort().map(([name,n])=>({name,n})))}</section></div><p class="muted">Un uso es un registro guardado, aunque incluya varias prendas. Con categoría seleccionada, los outfits y meses cuentan registros que incluyan esa categoría. Las correcciones se reflejan al guardar.</p><section class="panel"><h2>Compras por mes</h2><p class="muted">Cada moneda se muestra por separado. No se aplica conversión.</p>${Object.keys(s.expenses).length?`<div class="table-wrap"><table><thead><tr><th>Mes</th><th>Gasto registrado</th></tr></thead><tbody>${Object.entries(s.expenses).sort(([a],[b])=>b.localeCompare(a)).map(([key,n])=>{const [month,c]=key.split('|');return `<tr><td>${month}</td><td>${esc(money(n,c))}</td></tr>`;}).join('')}</tbody></table></div>`:'<p>No hay importes de compras fechadas en este periodo.</p>'}${s.purchases.length?`<details><summary>Ver ${s.purchases.length} compras del periodo</summary><ul class="plain-list">${s.purchases.sort((a,b)=>b.purchase_date.localeCompare(a.purchase_date)).map(g=>`<li><span>${esc(g.name)} · ${dateShort(g.purchase_date)}${g.store?' · '+esc(g.store):''}</span><strong>${g.price_minor!==null?esc(money(g.price_minor,g.currency)):'Sin precio'}</strong></li>`).join('')}</ul></details>`:''}<p class="muted">${s.gs.filter(g=>g.price_minor!==null&&!g.purchase_date).length} prendas con precio sin fecha de compra; no se asignan a un mes.</p></section><section class="panel"><h2>Tu ropa, con perspectiva</h2><p class="muted">Último uso y costo por uso consideran todo el historial, hasta hoy. El costo se muestra en la moneda de compra.</p>${s.gs.length?`<div class="table-wrap"><table><thead><tr><th>Prenda</th><th>Usos del periodo</th><th>Desde el último uso</th><th>Costo por uso histórico</th></tr></thead><tbody>${s.counts.map(({g,n})=>{const ws=data.wears.filter(w=>w.items.some(i=>i.id===g.id));const last=ws.map(w=>w.date).sort().at(-1);const days=last?Math.round((new Date(session.today+'T12:00:00Z')-new Date(last+'T12:00:00Z'))/86400000):null;return `<tr><td><button class="text-button" data-action="edit-garment" data-id="${g.id}">${esc(g.name)}</button>${g.archived?' · Archivada':''}</td><td>${n}</td><td>${last?`${days} días · ${dateShort(last)}`:'Nunca usada'}</td><td>${g.price_minor!==null&&ws.length?esc(money(g.price_minor/ws.length,g.currency)):'No disponible'}</td></tr>`;}).join('')}</tbody></table></div>`:'<p>Aquí aparecerán tus prendas cuando las añadas.</p>'}</section>`;}
function settingsView(){return `<div class="settings-grid"><section class="panel"><h2>Tu copia, contigo</h2><p>Descarga un ZIP con tus prendas, outfits, historial y fotos. Guárdalo en un lugar privado.</p><a class="primary button-link" href="api.php?action=export">Descargar respaldo completo ↓</a><p class="muted">No incluye tu contraseña. Haz una copia antes de cambios importantes.</p></section><section class="panel"><h2>Restaurar un respaldo</h2><p>Reemplaza los registros actuales con los de un respaldo de Mi armario. Primero verás qué contiene.</p><label class="file-button">Elegir respaldo ZIP<input id="backup-file" type="file" accept=".zip,application/zip"></label><p class="muted">Máximo 128 MB por archivo y 256 MB descomprimidos; el alojamiento puede imponer un límite menor.</p><a class="text-button" href="api.php?action=recovery">Descargar copia anterior a la última restauración</a></section><section class="panel"><h2>En tu iPhone</h2><ol><li>Abre la dirección HTTPS de tu armario en Safari.</li><li>Pulsa Compartir.</li><li>Selecciona «Añadir a pantalla de inicio».</li></ol><p>Necesitas conexión para ver y guardar tu ropa. No hay guardado ni sincronización sin conexión.</p>${session.local?'<p class="notice">Esta prueba está en tu Mac. El iPhone usará la dirección del alojamiento cuando esté publicada.</p>':''}</section><section class="panel"><h2>Acceso privado</h2><p>Una sola cuenta, sin registro público. Las fotos se entregan únicamente al iniciar sesión.</p><p class="muted">Para recuperar o cambiar la contraseña, utiliza la herramienta de instalación con ayuda de tu tío. No se envían correos.</p><button class="small-button" data-action="logout">Cerrar sesión</button></section></div>`;}
function openModal(title,html){modal.innerHTML=`<div class="modal-heading"><h2 id="modal-title">${esc(title)}</h2><button class="icon-button" data-action="close-modal" aria-label="Cerrar">×</button></div>${html}`;modal.showModal();}
function field(label,name,value='',type='text',extra=''){return `<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;}
function photoPicker(id,optional=false){return `<div class="photo-upload">${id?`<img id="photo-preview" src="${photo(id)}" alt="Foto seleccionada">`:'<div id="photo-preview" class="photo-placeholder">Tu foto aquí</div>'}<div><p>${optional?'Foto del conjunto · opcional':'Foto de la prenda'}</p><div class="photo-buttons"><label class="file-button">Elegir foto<input type="file" name="gallery" accept="image/*"></label><label class="file-button">Tomar foto<input type="file" name="camera" accept="image/*" capture="environment"></label></div><small>JPEG, PNG o WebP. Reducimos el tamaño y quitamos los datos de ubicación.</small>${optional&&id?'<label class="check-line"><input type="checkbox" name="remove_photo">Quitar foto del conjunto</label>':''}</div></div>`;}
function errorSlot(){return '<p class="form-error error" role="alert" hidden></p>';}
function footer(label='Guardar'){return `${errorSlot()}<div class="form-footer"><button type="button" class="small-button" data-action="close-modal">Cancelar</button><button type="submit" class="primary">${label}</button></div>`;}
let chosenPhoto=null;
const sizeOptions=['XXS','XS','S','M','L','XL','XXL','XXXL','Talla única',...Array.from({length:29},(_,i)=>String(i+28))];
const pantsOptions=['Recto','Slim','Regular','Relaxed','Bootcut','Skinny','Fit','Cargo','Chino','Jogger','Palazzo','Jeans rectos'];
const colorOptions=['Negro','Blanco','Gris','Beige','Marrón','Azul','Verde','Rojo','Rosa','Morado','Amarillo','Naranja','Multicolor'];
function savedOptions(values,value,blank){return options(value&&!values.includes(value)?[...values,value]:values,value,blank);}
function tagEditor(selected=[],kind='outfits'){
 const seen=new Set();const available=[...selected,...data[kind].flatMap(x=>x.tags||[]),...(kind==='outfits'?['Casual','Informal','Formal','Para la casa']:[])].filter(t=>{const key=t.toLocaleLowerCase('es');if(seen.has(key))return false;seen.add(key);return true;});
 return `<fieldset class="tag-editor"><legend>Etiquetas · opcionales</legend><p class="muted">Selecciona varias o crea una propia. Solo se guardan las seleccionadas.</p><div class="tag-choices">${available.map(t=>`<label class="tag-choice"><input type="checkbox" name="tags" value="${esc(t)}" ${selected.includes(t)?'checked':''}><span>${esc(t)}</span></label>`).join('')}</div><div class="tag-create"><label>Nueva etiqueta<input id="custom-tag" type="text" maxlength="60" placeholder="Escribe tu etiqueta"></label><button type="button" class="small-button" data-action="add-tag">Añadir etiqueta</button></div></fieldset>`;
}
function pantsInput(label,name,value,max,presets=[]){
 const seen=new Set();const values=[value,...data.garments.filter(isPants).map(g=>g[name]),...presets].filter(v=>{if(!v)return false;const k=v.toLocaleLowerCase('es');if(seen.has(k))return false;seen.add(k);return true;});
 return `<label>${label}<input name="${name}" value="${esc(value)}" list="suggest-${name}" maxlength="${max}" placeholder="Sin especificar"><datalist id="suggest-${name}">${values.map(v=>`<option value="${esc(v)}"></option>`).join('')}</datalist></label>`;
}
function garmentForm(id){const g=data.garments.find(g=>g.id===id)||{};chosenPhoto=null;openModal(id?'Detalle de prenda':'Añadir prenda',`<form id="garment-form" data-id="${g.id||''}" data-revision="${data.revision}">${photoPicker(g.photo)}<div class="form-grid">${field('Nombre','name',g.name,'text','required maxlength="120" placeholder="Ej. Camisa blanca de lino"')}<label>Categoría<select name="category" required>${options(session.categories,g.category,'Elige categoría')}</select></label><label>Color<input name="color" list="garment-colors" value="${esc(g.color)}" required maxlength="60" placeholder="Selecciona o escribe un color"><datalist id="garment-colors">${colorOptions.map(c=>`<option value="${c}"></option>`).join('')}</datalist></label><label id="generic-size-field" ${isPants(g)?'hidden':''}>Talla · opcional<select name="size">${savedOptions(sizeOptions,g.size,'Sin especificar')}</select></label><div id="pants-field" class="pants-fields" ${isPants(g)?'':'hidden'}>${pantsInput('Tipo de pantalón · selecciona o escribe','pants_type',g.pants_type,60,pantsOptions)}${field('Modelo / referencia · opcional','pants_model',g.pants_model,'text','maxlength="120"')}${pantsInput('Cintura · opcional','waist',g.waist,30)}${pantsInput('Largo · opcional','length',g.length,30)}<p class="muted pants-size-help">Cintura y largo se guardan por separado. Usa la medida de la etiqueta, sin convertir unidades.${g.size?` Talla anterior conservada: ${esc(g.size)}.`:''}</p></div></div><label>Notas<textarea name="notes" maxlength="2000" rows="3">${esc(g.notes)}</textarea></label>${tagEditor(g.tags,'garments')}<details ${g.price_minor!==null&&g.price_minor!==undefined||g.purchase_date||g.store?'open':''}><summary>Datos de compra · opcionales</summary><div class="form-grid">${field('Fecha de compra','purchase_date',g.purchase_date,'date',`max="${session.today}" min="1900-01-01"`)}${field('Tienda','store',g.store,'text','maxlength="120"')}${field('Precio','price',g.price_minor!==undefined&&g.price_minor!==null?(g.price_minor/10**(session.currencies[g.currency]??2)).toFixed(session.currencies[g.currency]??2):'','text','inputmode="decimal" placeholder="0,00"')}<label>Moneda<select name="currency">${options(Object.keys(session.currencies),g.currency||'NIO','Elige moneda')}</select></label></div></details>${id?`<label class="check-line"><input type="checkbox" name="archived" ${g.archived?'checked':''}>Archivar prenda · conserva su historial</label>`:''}${footer()}</form>`);}
function picker(ids=[]){return `<div class="picker-tools"><label>Buscar prendas para seleccionar<input type="search" id="picker-search" placeholder="Nombre o categoría"></label></div><div class="picker">${data.garments.filter(g=>!g.archived||ids.includes(g.id)).map(g=>`<label class="pick-item" data-search="${esc((g.name+' '+g.category+' '+g.color).toLocaleLowerCase('es'))}"><input type="checkbox" name="garment_ids" value="${g.id}" ${ids.includes(g.id)?'checked':''}>${garmentImage(g)}<span>${esc(g.name)}${g.archived?' · Archivada':''}</span></label>`).join('')}</div>`;}
function outfitForm(id){if(!data.garments.length){notify('Primero añade una prenda a tu armario.');garmentForm();return;}const o=data.outfits.find(o=>o.id===id)||{};chosenPhoto=null;openModal(id?'Editar outfit':'Crear outfit',`<form id="outfit-form" data-id="${o.id||''}" data-revision="${data.revision}">${field('Nombre del outfit','name',o.name,'text','required maxlength="120" placeholder="Ej. Viernes en la oficina"')}<label>Notas<textarea name="notes" maxlength="2000" rows="2">${esc(o.notes)}</textarea></label>${tagEditor(o.tags)}${photoPicker(o.photo,true)}<h3>Prendas del outfit</h3>${picker(o.garment_ids)}<p class="muted">Guardar esta combinación no registra un uso ni cambia usos anteriores.</p>${footer('Guardar outfit')}</form>`);}
function wearForm(id,outfitId){if(!data.garments.length){notify('Primero añade una prenda a tu armario.');garmentForm();return;}const w=data.wears.find(w=>w.id===id);const o=data.outfits.find(o=>o.id===(w?.outfit_id||outfitId));const ids=w?w.items.map(i=>i.id):(o?.garment_ids||[]);openModal(w?'Corregir uso':'Registrar lo que llevo',`<form id="wear-form" data-id="${w?.id||''}" data-revision="${data.revision}"><div class="form-grid">${field('Fecha de uso','date',w?.date||(page==='calendar'?selectedDay:session.today),'date',`required min="1900-01-01" max="${session.today}"`)}<label>Outfit de origen<select name="outfit_id" id="wear-outfit"><option value="">Combinación del día</option>${data.outfits.map(x=>`<option value="${x.id}" ${o?.id===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label></div><h3>Lo que llevaste ese día</h3><p class="muted">Puedes quitar o añadir prendas aquí. El outfit original no cambia.</p><div id="wear-picker">${picker(ids)}</div><label>Notas del día · opcionales<textarea name="notes" maxlength="2000" rows="2">${esc(w?.notes)}</textarea></label>${w?'<button type="button" class="danger-text" data-action="delete-wear" data-id="'+w.id+'">Eliminar este registro de uso</button>':''}${footer(w?'Guardar corrección':'Guardar uso')}</form>`);}
async function preparePhoto(file){
 if(file.size>20*1024*1024)throw Error('La foto supera 20 MB. Elige una más pequeña.');
 let bitmap;try{bitmap=await createImageBitmap(file,{imageOrientation:'from-image'});}catch{throw Error('No se pudo leer esa foto. Usa JPEG, PNG o WebP. Si es HEIC, expórtala como JPEG.');}
 const scale=Math.min(1,1600/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();
 const blob=await new Promise(r=>canvas.toBlob(r,'image/jpeg',.88));if(!blob)throw Error('No se pudo preparar la foto.');return blob;
}
async function uploadPhoto(existing){if(!chosenPhoto)return existing||null;const fd=new FormData();fd.append('photo',chosenPhoto,'photo.jpg');return(await api('upload',fd)).id;}
function parsePrice(raw,currency){raw=raw.trim().replace(',','.');if(!raw)return null;const decimals=session.currencies[currency];if(decimals===undefined)throw Error('Elige una moneda.');const regex=decimals===0?/^\d{1,10}$/:/^\d{1,10}(\.\d{1,2})?$/;if(!regex.test(raw))throw Error('Escribe el precio sin separadores de miles y con los decimales de la moneda.');const [whole,frac='']=raw.split('.');return Number(whole)*10**decimals+Number(frac.padEnd(decimals,'0'));}
function showFormError(form,e){const box=form.querySelector('.form-error');box.hidden=false;box.textContent=e.message;}
async function saveForm(form){const button=form.querySelector('[type="submit"]');button.disabled=true;const fd=new FormData(form),id=form.dataset.id;try{let item={},kind='';if(form.id==='garment-form'){kind='garments';const old=data.garments.find(g=>g.id===id);item={name:fd.get('name'),category:fd.get('category'),color:fd.get('color'),size:fd.get('size'),pants_type:fd.get('pants_type'),pants_model:fd.get('pants_model'),waist:fd.get('waist'),length:fd.get('length'),tags:fd.getAll('tags'),notes:fd.get('notes'),purchase_date:fd.get('purchase_date')||null,store:fd.get('store'),currency:fd.get('currency'),price_minor:parsePrice(fd.get('price'),fd.get('currency')),archived:fd.has('archived'),photo:await uploadPhoto(old?.photo)};}else if(form.id==='outfit-form'){kind='outfits';const old=data.outfits.find(o=>o.id===id);item={name:fd.get('name'),tags:fd.getAll('tags'),notes:fd.get('notes'),garment_ids:fd.getAll('garment_ids'),photo:fd.has('remove_photo')?null:await uploadPhoto(old?.photo)};}else{kind='wears';item={date:fd.get('date'),notes:fd.get('notes'),outfit_id:fd.get('outfit_id')||null,garment_ids:fd.getAll('garment_ids')};}if(id)item.id=id;await api('save',{kind,item,revision:Number(form.dataset.revision)});modal.close();await refresh();notify(kind==='wears'?'Uso guardado. Historial y estadísticas actualizados.':'Guardado en tu armario.');}catch(e){showFormError(form,e);}finally{button.disabled=false;}}
function renderLogin(){root.classList.remove('wardrobe');root.innerHTML=`<main class="login"><div class="login-brand"><span class="monogram">M</span> mi armario</div><section class="login-card"><p class="eyebrow">SOLO PARA TI</p><h1>${session.setup?'Tu armario empieza aquí.':'Qué bueno verte.'}</h1><p>${session.setup?'Crea la contraseña de tu cuenta privada. Solo se hace una vez en esta Mac.':'Entra para ver tu ropa y guardar lo que llevas hoy.'}</p><form id="login-form">${field(session.setup?'Elige una contraseña':'Tu contraseña','password','','password',`required minlength="${session.setup?12:1}" maxlength="128" autocomplete="${session.setup?'new-password':'current-password'}"`)}${session.setup?field('Repite la contraseña','confirm','','password','required minlength="12" maxlength="128" autocomplete="new-password"'):''}${errorSlot()}<button type="submit" class="primary">${session.setup?'Crear mi acceso privado':'Entrar a mi armario'} →</button></form><p class="muted">${session.setup?'Al menos 12 caracteres. Guárdala en tu gestor de contraseñas.':'Una cuenta. Tus prendas. Tu espacio.'}</p></section><p class="login-foot">${session.local?'Prueba local en tu Mac · los datos se guardan en esta computadora':'Necesitas conexión para consultar y guardar tu ropa'}</p></main>`;}
async function restorePreview(file){const fd=new FormData();fd.append('backup',file);notify('Comprobando el respaldo y sus fotos…');const b=await api('preview-import',fd);openModal('Revisar restauración',`<form id="restore-form" data-token="${b.token}" data-revision="${data.revision}"><p>Este respaldo contiene:</p><ul><li>${b.garments} prendas</li><li>${b.outfits} outfits</li><li>${b.wears} registros de uso</li><li>${b.photos} fotos</li></ul><p class="notice">Se sustituirán tus ${data.garments.length} prendas, ${data.outfits.length} outfits y ${data.wears.length} usos actuales. Se conservará una copia anterior a esta restauración.</p><label class="check-line"><input name="confirm" type="checkbox" required>Entiendo que se reemplazarán mis registros actuales.</label>${footer('Restaurar este respaldo')}</form>`);}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action],[data-page]');if(!b)return;try{if(b.dataset.page){page=b.dataset.page;render();window.scrollTo(0,0);return;}const id=b.dataset.id;switch(b.dataset.action){case'add-tag':{const input=modal.querySelector('#custom-tag'),tag=input.value.trim();if(!tag){input.focus();break;}const existing=[...modal.querySelectorAll('[name="tags"]')].find(x=>x.value.toLocaleLowerCase('es')===tag.toLocaleLowerCase('es'));if(existing){existing.checked=true;}else{if(modal.querySelectorAll('[name="tags"]:checked').length>=30){notify('Usa como máximo 30 etiquetas.');break;}const label=document.createElement('label');label.className='tag-choice';const check=document.createElement('input');check.type='checkbox';check.name='tags';check.value=tag;check.checked=true;const span=document.createElement('span');span.textContent=tag;label.append(check,span);modal.querySelector('.tag-choices').append(label);}input.value='';input.focus();break;}case'close-modal':modal.close();break;case'refresh':session=await api('session');await refresh();notify('Datos actualizados.');break;case'logout':await api('logout',{});data={garments:[],outfits:[],wears:[],revision:0};session=await api('session');renderLogin();break;case'new-garment':garmentForm();break;case'edit-garment':garmentForm(id);break;case'new-outfit':outfitForm();break;case'edit-outfit':outfitForm(id);break;case'new-wear':wearForm();break;case'edit-wear':wearForm(id);break;case'wear-outfit':wearForm(null,id);break;case'select-day':selectedDay=b.dataset.date;render();break;case'prev-month':case'next-month':{const d=new Date(calendarMonth+'-15T12:00:00');d.setMonth(d.getMonth()+(b.dataset.action==='next-month'?1:-1));calendarMonth=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;render();break;}case'clear-stats':statsFilter={from:'',to:'',category:''};render();break;case'delete-wear':if(confirm('¿Eliminar este uso? Se quitará del historial y de las estadísticas.')){await api('delete-wear',{id,revision:Number(document.querySelector('#wear-form').dataset.revision)});modal.close();await refresh();notify('Uso eliminado.');}break;}}catch(error){notify(error.message);}});
document.addEventListener('input',e=>{if(e.target.id==='clothing-q'){clothingFilter.q=e.target.value;document.querySelector('#clothing-results').innerHTML=garmentResults();}if(e.target.id==='picker-search'){const q=e.target.value.toLocaleLowerCase('es');modal.querySelectorAll('.pick-item').forEach(x=>x.hidden=!x.dataset.search.includes(q));}});
document.addEventListener('change',async e=>{try{const x=e.target;if(x.id==='spending-period'){spendingPeriod=x.value;const panel=x.closest('.spending-panel');panel.outerHTML=spendingView();document.querySelector('#spending-period').focus();}if(x.name==='category'&&x.form?.id==='garment-form'){const pants=isPants({category:x.value});modal.querySelector('#pants-field').hidden=!pants;modal.querySelector('#generic-size-field').hidden=pants;}if(x.id==='clothing-category'||x.id==='clothing-archived'){clothingFilter[x.id==='clothing-category'?'category':'archived']=x.value;document.querySelector('#clothing-results').innerHTML=garmentResults();}if(x.id.startsWith('stats-')){statsFilter[x.id.slice(6)]=x.value;render();}if(x.id==='calendar-month'&&x.value){calendarMonth=x.value;render();}if(x.id==='wear-outfit'){const o=data.outfits.find(o=>o.id===x.value);document.querySelector('#wear-picker').innerHTML=picker(o?.garment_ids||[]);}if(x.type==='file'&&['gallery','camera'].includes(x.name)&&x.files[0]){const submit=x.form.querySelector('[type="submit"]');submit.disabled=true;try{const blob=await preparePhoto(x.files[0]);chosenPhoto=blob;const img=document.createElement('img');img.id='photo-preview';img.alt='Foto seleccionada';const url=URL.createObjectURL(blob);img.onload=()=>URL.revokeObjectURL(url);img.src=url;document.querySelector('#photo-preview').replaceWith(img);notify('Foto lista para guardar.');}finally{submit.disabled=false;}}if(x.id==='backup-file'&&x.files[0]){x.disabled=true;try{await restorePreview(x.files[0]);}finally{x.disabled=false;x.value='';}}}catch(error){notify(error.message);}});
document.addEventListener('submit',async e=>{e.preventDefault();const f=e.target;if(['garment-form','outfit-form','wear-form'].includes(f.id)){await saveForm(f);return;}const b=f.querySelector('[type="submit"]');if(!b)return;b.disabled=true;try{if(f.id==='login-form'){const fd=new FormData(f);if(session.setup&&fd.get('password')!==fd.get('confirm'))throw Error('Las contraseñas no coinciden.');await api(session.setup?'setup':'login',{password:fd.get('password')});session=await api('session');await refresh();}if(f.id==='restore-form'){await api('restore',{token:f.dataset.token,revision:Number(f.dataset.revision)});modal.close();await refresh();notify('Respaldo restaurado con sus fotos.');}}catch(error){showFormError(f,error);}finally{b.disabled=false;}});
window.addEventListener('offline',()=>notify('Sin conexión. No se guardarán cambios hasta recuperar la conexión.'));
window.addEventListener('pageshow',e=>{if(e.persisted)location.reload();});
async function start(){try{session=await api('session');if(session.authenticated)await refresh();else renderLogin();if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js').catch(()=>{});}catch(e){root.innerHTML=`<main class="login"><section class="panel"><h1>No se pudo abrir el armario</h1><p>${esc(e.message)}</p><button class="primary" id="retry-start">Volver a intentar</button></section></main>`;document.querySelector('#retry-start').onclick=start;}}
start();
